    'manual.subtitulo': 'Portal do Cliente · catálogo, funil de vendas e identidade da marca',
    'manual.imprimir': '🖨️ Imprimir / PDF',
    'manual.s1.titulo': '1. Coleções e liberação',
    'manual.s1.p1': 'A coleção é a unidade onde as peças (modelo, estampa, tamanho) ficam agrupadas. Ela tem dois estados:',
    'manual.s1.li1a': 'Em preparação',
    'manual.s1.li1b': '— o gestor de estoque está cadastrando as peças. Ficam',
    'manual.s1.li1c': 'invisíveis',
    'manual.s1.li1d': 'para as vendedoras (não aparecem no PDV nem no catálogo).',
    'manual.s1.li2a': 'Liberada',
    'manual.s1.li2b': '— o gestor de estoque clica em',
    'manual.s1.li2c': 'liberar',
    'manual.s1.li2d': 'e a coleção passa a aparecer para',
    'manual.s1.li2e': 'todas as vendedoras ao mesmo tempo',
    'manual.s1.li2f': '.',
    'manual.s1.nota': 'Por que simultâneo? As vendedoras disputam o mesmo estoque. Liberar para todas no mesmo instante garante competição justa — ninguém larga na frente.',
    'manual.s1.onde1': 'Onde:',
    'manual.s1.onde2': 'menu',
    'manual.s1.onde3': 'Coleções',
    'manual.s1.onde4': '. O gestor de estoque cria, cadastra as peças em',
    'manual.s1.onde5': 'Produtos',
    'manual.s1.onde6': 'e depois libera.',
    'manual.s2.titulo': '2. Catálogo e link da vendedora',
    'manual.s2.p1': 'Cada vendedora tem um link próprio do catálogo, no formato:',
    'manual.s2.li1': 'A vendedora compartilha o link com a carteira de clientes dela.',
    'manual.s2.li2a': 'Quem abre vê as coleções liberadas (estética de loja) e, ao tocar em',
    'manual.s2.li2b': '"Falar com a vendedora"',
    'manual.s2.li2c': ', é direcionado para o',
    'manual.s2.li2d': 'WhatsApp dela',
    'manual.s2.li2e': '.',
    'manual.s2.li3a': 'Esse contato vira o',
    'manual.s2.li3b': 'ponto de entrada no CRM',
    'manual.s2.li3c': ': o cliente entra na carteira da vendedora e abre uma oportunidade no funil.',
    'manual.s2.onde1': 'Onde:',
    'manual.s2.onde2': 'menu',
    'manual.s2.onde3': 'Funil de vendas',
    'manual.s2.onde4': '→ "Links das vendedoras" (copiar e distribuir).',
    'manual.s3.titulo': '3. Funil de atendimento & vendas',
    'manual.s3.p1a': 'Cada ciclo de contato é uma',
    'manual.s3.p1b': 'oportunidade',
    'manual.s3.p1c': 'independente. Um mesmo cliente pode ter várias ao longo do tempo (perdeu hoje, volta depois = nova oportunidade). As etapas:',
    'manual.s3.li1a': 'Entrou',
    'manual.s3.li1b': '— chegou pelo catálogo; aguardando a 1ª resposta.',
    'manual.s3.li2a': 'Atendido',
    'manual.s3.li2b': '— a vendedora respondeu (atender = responder).',
    'manual.s3.li3a': 'Negociando',
    'manual.s3.li3b': '— atendimento ativo em andamento.',
    'manual.s3.li4a': 'Convertido',
    'manual.s3.li4b': '— virou venda (automático ao registrar a venda do cliente) ou marcado à mão.',
    'manual.s3.li5a': 'Perdido',
    'manual.s3.li5b': '— encerrado sem compra. O cliente pode reentrar e abrir um novo ciclo.',
    'manual.s3.nota': 'Reentrada: se já existe um ciclo aberto, ele é reaproveitado; se todos estão fechados, abre-se um novo ciclo.',
    'manual.s3.onde1': 'Onde:',
    'manual.s3.onde2': 'menu',
    'manual.s3.onde3': 'Funil de vendas',
    'manual.s3.onde4': '— quadro Kanban com métricas (abertos, atrasados, convertidos, taxa de conversão e tempo médio de 1ª resposta).',
    'manual.s4.titulo': '4. SLA por etapa e redistribuição',
    'manual.s4.p1a': 'Você define o',
    'manual.s4.p1b': 'tempo máximo',
    'manual.s4.p1c': 'que uma oportunidade pode ficar em cada etapa. Estourou o prazo, o card aparece como',
