    'manual.titulo': "Manager's Manual",
    'manual.subtitulo': 'Customer Portal · catalog, sales funnel, and brand identity',
    'manual.imprimir': '🖨️ Print / PDF',
    'manual.s1.titulo': '1. Collections and release',
    'manual.s1.p1': 'A collection is the unit where pieces (model, pattern, size) are grouped. It has two states:',
    'manual.s1.li1a': 'In preparation',
    'manual.s1.li1b': '— the inventory manager is registering the pieces. They stay',
    'manual.s1.li1c': 'invisible',
    'manual.s1.li1d': 'to salespeople (they do not appear in the POS or the catalog).',
    'manual.s1.li2a': 'Released',
    'manual.s1.li2b': '— the inventory manager clicks',
    'manual.s1.li2c': 'release',
    'manual.s1.li2d': 'and the collection starts appearing to',
    'manual.s1.li2e': 'all salespeople at the same time',
    'manual.s1.li2f': '.',
    'manual.s1.nota': 'Why simultaneous? Salespeople compete for the same stock. Releasing to everyone at the same instant ensures fair competition — no one gets a head start.',
    'manual.s1.onde1': 'Where:',
    'manual.s1.onde2': 'menu',
    'manual.s1.onde3': 'Collections',
    'manual.s1.onde4': '. The inventory manager creates it, registers the pieces in',
    'manual.s1.onde5': 'Products',
    'manual.s1.onde6': 'and then releases it.',
    'manual.s2.titulo': '2. Catalog and salesperson link',
    'manual.s2.p1': "Each salesperson has her own catalog link, in this format:",
    'manual.s2.li1': 'The salesperson shares the link with her customer portfolio.',
    'manual.s2.li2a': 'Whoever opens it sees the released collections (store look and feel) and, by tapping',
    'manual.s2.li2b': '"Talk to the salesperson"',
    'manual.s2.li2c': ', is directed to',
    'manual.s2.li2d': 'her WhatsApp',
    'manual.s2.li2e': '.',
    'manual.s2.li3a': 'This contact becomes the',
    'manual.s2.li3b': 'CRM entry point',
    'manual.s2.li3c': ": the customer joins the salesperson's portfolio and opens an opportunity in the funnel.",
    'manual.s2.onde1': 'Where:',
    'manual.s2.onde2': 'menu',
    'manual.s2.onde3': 'Sales funnel',
    'manual.s2.onde4': '→ "Salespeople links" (copy and distribute).',
    'manual.s3.titulo': '3. Sales & follow-up funnel',
    'manual.s3.p1a': 'Each contact cycle is an independent',
    'manual.s3.p1b': 'opportunity',
    'manual.s3.p1c': '. The same customer can have several over time (lost today, comes back later = new opportunity). The stages:',
    'manual.s3.li1a': 'New',
    'manual.s3.li1b': '— came in through the catalog; waiting for the 1st response.',
    'manual.s3.li2a': 'Attended',
    'manual.s3.li2b': '— the salesperson replied (attend = respond).',
    'manual.s3.li3a': 'Negotiating',
    'manual.s3.li3b': '— active service in progress.',
    'manual.s3.li4a': 'Converted',
    'manual.s3.li4b': "— became a sale (automatic when logging the customer's sale) or marked by hand.",
    'manual.s3.li5a': 'Lost',
    'manual.s3.li5b': '— closed without a purchase. The customer can come back and open a new cycle.',
    'manual.s3.nota': 'Re-entry: if an open cycle already exists, it is reused; if all are closed, a new cycle opens.',
    'manual.s3.onde1': 'Where:',
    'manual.s3.onde2': 'menu',
    'manual.s3.onde3': 'Sales funnel',
    'manual.s3.onde4': '— Kanban board with metrics (open, overdue, converted, conversion rate, and average 1st-response time).',
    'manual.s4.titulo': '4. SLA per stage and redistribution',
    'manual.s4.p1a': 'You set the',
    'manual.s4.p1b': 'maximum time',
    'manual.s4.p1c': 'an opportunity can stay in each stage. Once the deadline is exceeded, the card shows as',
    'manual.s4.p1d': 'overdue',
    'manual.s4.p1e': '.',
    'manual.s4.li1a': 'New:',
    'manual.s4.li1b': 'deadline for the 1st response. Once exceeded, the manager can redistribute it (or the system redistributes it automatically, if that option is on) to the least busy salesperson.',
    'manual.s4.li2a': 'Attended / Negotiating:',
    'manual.s4.li2b': 'deadlines to move forward; they flag stalled opportunities.',
    'manual.s4.p2a': "Redistributing moves the opportunity and the customer's portfolio to another salesperson and resets the deadline. Use the",
    'manual.s4.p2b': '↪',
    'manual.s4.p2c': 'button on the card or',
    'manual.s4.p2d': 'Redistribute overdue',
    'manual.s4.p2e': '.',
    'manual.s4.onde1': 'Where:',
    'manual.s4.onde2': 'menu',
    'manual.s4.onde3': 'Brand',
    'manual.s4.onde4': '(configures the deadlines and automatic redistribution).',
    'manual.s5.titulo': '5. Brand identity',
