    'manual.s5.li2a': 'Colors:',
    'manual.s5.li2b': 'primary color (buttons/CTA) and background color.',
    'manual.s5.onde1': 'Where:',
    'manual.s5.onde2': 'menu',
    'manual.s5.onde3': 'Brand',
    'manual.s5.onde4': '.',
    'manual.s6.titulo': '6. Brand campaigns',
    'manual.s6.p1a': 'Centralize campaigns: you',
    'manual.s6.p1b': 'build it once',
    'manual.s6.p1c': 'and salespeople',
    'manual.s6.p1d': 'send it',
    'manual.s6.p1e': 'to their own portfolio.',
    'manual.s6.li1a': 'Create the campaign with',
    'manual.s6.li1b': 'name',
    'manual.s6.li1c': ',',
    'manual.s6.li1d': 'suggested segment',
    'manual.s6.li1e': ',',
    'manual.s6.li1f': 'message',
